CT.en.EP=[["Meeting a teacher at school", "(Walk by pretending not to see)", "Hello, teacher!", "When you meet an adult, bow and say hello first"], ["Wanting to talk in class", "Me me me! Let me talk!!", "(Raise a hand and wait)", "Raise your hand and wait your turn to talk"], ["When a friend presents", "Haha, that's wrong~", "(Listen carefully to the end)", "Listen to the end when a friend is talking"], ["In the hallway", "Let's race down the hallway!", "Tiptoe gently in the hallway", "Walk, don't run, and keep right in the hallway"], ["At lunchtime", "I'll skip the line and go first!", "Line up and wait my turn", "Line up and take lunch in turn"], ["Wanting a friend's things", "(Take it without asking)", "May I borrow this for a bit?", "Always ask before borrowing others' things"], ["Leaving the classroom", "(Leave the chair sticking out)", "Push the chair in!", "Push in your chair when you leave"], ["When the teacher speaks", "(Play around with a friend)", "(Look and listen well)", "Listen to the teacher sitting nicely"], ["Grandma carrying bags", "(Just walk past)", "Grandma, let me help you!", "Help adults who are struggling"], ["Giving something to Grandpa", "(Hand it over with one hand)", "(With two hands) Here you go!", "Give things to elders with two hands"], ["Meeting a police officer", "(Ignore them)", "Thank you for your hard work!", "Thank the people who keep us safe"], ["Asking restaurant staff", "Get me water!", "May I have some water? Thank you!", "Say \"please\" to ask and \"thank you\" when you get it"], ["When the delivery person comes", "(Just open the door and go in)", "Thank you! Goodbye!", "Show thanks to people who work for us"], ["With the doctor at the hospital", "No shots! I won't!", "It's scary, but I'll be brave!", "When you're sick, listen to the doctor"], ["At the supermarket", "Let's ride the cart, whoosh~!", "Push the cart slowly", "Push carts slowly at the supermarket"], ["Seeing snacks at the market", "Buy it! Or I'll cry!", "I'll pick just one today", "Don't whine; pick only what you promised"], ["At a free sample stand", "(Eat lots at once)", "Just one, thank you!", "Take just one sample and say thank you"], ["At the movie theater", "Crunch crunch popcorn! Let's be loud!", "(Watch quietly, whispering)", "Watch quietly at the theater"], ["In the theater seat", "Kick-kick the seat in front!", "Feet nicely on the floor~", "Don't kick the seat in front of you"], ["At the museum", "I want to touch this!", "I'll just look with my eyes", "Look at exhibits only with your eyes"], ["Inside the museum", "Wow! Let's play echo~", "(Talk in a small voice)", "Use a quiet voice in exhibit halls"], ["At the pool", "Race by the pool!", "It's slippery, walk slowly", "Don't run by the pool"], ["Before getting in the pool", "Splash right in~!", "Shower first, then go in", "Shower and warm up before getting in"], ["Getting on the subway", "(Get on before people get off)", "People getting off first~", "Let people off first, then get on"], ["On the subway", "Monkey bars on the handles!", "Hold the handle and stand", "Hold on and stand nicely on the subway"], ["Riding a taxi", "(Sit without a seatbelt)", "Seatbelt — click!", "Buckle up as soon as you get in a car"], ["On an airplane", "Let's kick the seat ahead!", "(Sit nicely in my seat)", "Be considerate of others on a plane"], ["Riding a bike", "Zoom without a helmet!", "Helmet on, let's go!", "Always wear a helmet on a bike"], ["Riding a scooter", "Let's zoom on the road!", "I'll ride slowly in the park", "Ride scooters slowly in safe places"], ["At the crosswalk by school", "Mom! Let's just cross here!", "Cross at the crosswalk", "Always cross at the crosswalk"], ["In a parking lot", "Hide-and-seek between cars!", "Hold Mom's hand tight", "Hold an adult's hand in parking lots"], ["When the light is blinking", "Blink blink! Run quick!", "Wait for the next green light", "Don't cross when the light is blinking"], ["When there's a fire", "Let's take the elevator down!", "Stairs! Cover nose and mouth!", "In a fire, take the stairs and cover your nose and mouth"], ["A stranger says \"come with me\"", "Candy! I'll go!", "No! I'll ask my mom", "Never go with a stranger"], ["Answering the phone", "Who is it? What?", "Hello, who's calling please?", "Answer the phone politely"], ["Entering a room", "(Fling the door open)", "Knock knock, may I come in?", "Knock before entering a room"], ["Before a meal", "(Eat before the adults)", "Thank you for the food!", "Start eating after the adults do"], ["After eating", "(Leave the dishes and go play)", "That was yummy! Dishes to the sink~", "Take your own dishes to the sink"], ["With chopsticks", "Chopstick sword fight!", "Chopsticks are for food only", "Don't play with spoons or chopsticks"], ["While eating", "Talking with a full mouth, munch munch!", "Chew well, swallow, then talk", "Don't talk with food in your mouth"], ["When there's yummy cake", "The biggest one is mine!", "Let's share", "Share yummy things together"], ["Spilling milk", "(Pretend nothing happened and run)", "Mom, I'll wipe it up!", "When you make a mistake, say so and clean up"], ["At bath time", "Water play! A flood in the bathroom~", "Water stays in the tub!", "Don't splash water during a bath"], ["Before bed", "I'll brush tomorrow~", "Brush brush, all clean!", "Always brush your teeth before bed"], ["Taking off clothes", "(Throw clothes on the floor)", "Laundry goes in the basket!", "Put worn clothes in the laundry basket"], ["Waking up in the morning", "(Leave the blanket messy)", "Blanket folded!", "Tidy your bed when you get up"], ["At the front door", "(Kick shoes off anywhere)", "Shoes neatly side by side!", "Line up your shoes neatly"], ["Taking off a coat", "(Toss it on the sofa)", "Hang it on a hanger", "Hang your coat on a hanger"], ["When there's trash", "(Leave it on the floor)", "Into the recycling bin!", "Sort your trash when you throw it away"], ["Leaving a room", "(Leave the light on)", "Lights off, then go", "Turn off unused lights to save power"], ["Watching TV", "I'll watch right up close!", "I'll sit far away", "Watch TV from afar, only for the promised time"], ["Using a smartphone", "Just a bit more! A bit more!", "Time's up! I'll stop", "Use the phone only for the promised time"], ["Walking on the street", "(Walk while looking at the phone)", "Eyes ahead when walking", "Don't look at your phone while walking"], ["Losing a game", "Ugh! I quit!", "I'll win next time! That was fun", "Don't get angry when you lose; have fun"], ["A friend asks to play", "No, go away!", "Sure, let's play!", "Speak kindly to friends"], ["A new friend arrives", "(Ignore them)", "Hi! Want to play with me?", "Go up to new friends first"], ["A gift you don't like", "This is meh!", "Thank you! I'll use it", "Be thankful for the heart behind a gift"], ["On a friend's birthday", "(Just eat cake, no wishes)", "Happy birthday!", "Celebrate a friend's happy day together"], ["Wanting a friend's toy", "Mine! (grab it)", "Can we play with it together?", "Don't grab; ask to play together"], ["Sharing crayons", "These are all mine!", "Let's use them together!", "Share things nicely"], ["Learning a friend's secret", "Everyone! I'll tell you a secret~", "I'll keep your secret", "Keep your friend's secrets"], ["When a friend is crying", "(Walk by laughing)", "Are you okay? What happened?", "Comfort a friend who is upset"], ["When I win", "Nyah nyah~ I won!", "That was fun! Let's play again", "Think of your friend's feelings even when you win"], ["Waiting for a turn", "Me first! Me first!", "You go first, I'm next!", "Take turns when playing"], ["When my little sibling cries", "Too noisy! Be quiet!", "Are you okay? I'll play with you", "Care for younger siblings kindly"], ["Sibling ruined my drawing", "(Push the sibling)", "Please be careful next time~", "Even when angry, use your words"], ["Big sibling is studying", "Let's play! Bang bang!", "(Play quietly alone)", "Be quiet when family is studying"], ["Mom and Dad are busy", "Play with me right now!", "I'll wait — can I help?", "When family is busy, wait and help"], ["Guests come over", "(Hide in my room)", "Welcome, hello!", "Greet guests warmly"], ["Visiting Grandma's house", "(Turn on TV without hello)", "Grandma, I missed you!", "Say hello first at an elder's home"], ["At the park flower bed", "I'll pick a pretty flower!", "Just look, and snap a photo!", "Don't pick flowers or break trees"], ["On the lawn", "Ignore the sign and go in!", "I'll follow \"Keep off\"", "Follow the signs"], ["Meeting a puppy", "A puppy! Big hug!", "I'll ask first if I can pet it", "Ask before petting someone's dog"], ["Seeing ants", "Let's step on them!", "Hi ants~ I'll pass gently", "Treasure even tiny lives"], ["At the beach", "Let's bury trash in the sand!", "Take trash back home", "Leave no trash in nature"], ["In the mountains", "Yoo-hoo! Yoo-hoooo!", "(Listen quietly to the forest)", "Be quiet in the mountains for animal friends"], ["Using water", "Brush with the tap running~", "Use a cup", "Save water"], ["Having a cold", "The mask is stuffy, off it goes!", "I'll wear a mask for my friends", "When sick, protect friends with a mask"], ["About to sneeze", "Achoo~! (just sneeze)", "(Cover with elbow) Achoo!", "Cover coughs and sneezes with your elbow"], ["Taking medicine", "I thought it was candy~ yum", "Only when an adult gives it", "Take medicine only with an adult"], ["Falling and getting hurt", "(Hide it even if it hurts)", "Mom, I got hurt", "Tell an adult right away when hurt"], ["After eating candy", "Toss the wrapper~", "Wrapper in my pocket, then the bin", "Throw trash in the trash can"], ["At bedtime", "More play! No sleep!", "Good night~", "Go to bed on time"], ["Morning greeting", "(Go eat without a word)", "Did you sleep well?", "Greet your family first in the morning"], ["Packing my bag", "Mom, pack it for me!", "I'll pack my own bag", "Take care of your own things"], ["Getting pocket money", "Let's spend it all!", "I'll save half", "Spend carefully and save your money"]];
/*EP-END*/

