CT.en.DW=["Dad", "Mom", "Grandma", "Grandpa", "a baby", "me", "a friend", "big brother", "big sister", "a teacher", "a police officer", "a firefighter", "a doctor", "a chef", "a princess", "a prince", "a wizard", "an astronaut", "a robot", "a snowman", "Santa", "a fairy", "a puppy", "a cat", "a bunny", "a bear", "a panda", "a lion", "a tiger", "an elephant", "a giraffe", "a monkey", "a penguin", "a turtle", "a frog", "a fish", "a whale", "an octopus", "a butterfly", "a bee", "a ladybug", "a snail", "a chick", "a cow", "a pig", "a horse", "a dinosaur", "a unicorn", "a dragon", "a star", "the moon", "the sun", "a cloud", "a rainbow", "rain", "snowflakes", "lightning", "a tree", "a sunflower", "a tulip", "cherry blossoms", "a mushroom", "a cactus", "a mountain", "the sea", "an island", "a volcano", "Saturn", "the Earth", "a shooting star", "fallen leaves", "our house", "a school", "a castle", "a tent", "a Ferris wheel", "a merry-go-round", "a slide", "a sandy beach", "a car", "a bus", "a train", "an airplane", "a rocket", "a bike", "a sailboat", "a fire truck", "a police car", "a helicopter", "a UFO", "balloons", "a kite", "a garden", "an apple", "a banana", "a strawberry", "a watermelon", "ice cream", "a birthday cake", "a donut", "pizza", "a rice ball", "a lollipop", "a teddy bear", "a soccer ball", "an umbrella", "a backpack", "a crown", "a present", "a Christmas tree", "crayons", "books", "a guitar", "a drum", "a yo-yo"];
